package main
import("bytes";"context";"crypto/rand";"database/sql";"encoding/hex";"encoding/json";"fmt";"io";"mime/multipart";"net/http";"net/http/httptest";"net/url";"os";"strings";"testing";"time")
func TestLegalLive(t *testing.T){
 if os.Getenv("HARMONIKA_LEGAL_LIVE")!="1"{t.Skip("isolated opt-in")}
 db,e:=sql.Open("pgx",os.Getenv("DATABASE_URL"));if e!=nil{t.Fatal("DB unavailable")};defer db.Close();ctx,cancel:=context.WithTimeout(context.Background(),180*time.Second);defer cancel();ids:=[]int64{};keys:=[]string{}
 defer func(){for _,id:=range ids{db.Exec("DELETE FROM public_ai_requests WHERE token_id=$1",id);db.Exec("DELETE FROM public_ai_tokens WHERE id=$1",id)}}()
 for _,tier:=range []string{"public","internal"}{raw:=make([]byte,32);rand.Read(raw);key:="hai_live_"+hex.EncodeToString(raw);var id int64
  if db.QueryRowContext(ctx,`INSERT INTO public_ai_tokens(token_hash,name,owner_chat_id,scopes,tier,request_limit_per_day) VALUES($1,'isolated-legal-smoke','isolated-legal-smoke','chat,models',$2,100) RETURNING id`,hashToken(key),tier).Scan(&id)!=nil{t.Fatal("fixture token creation failed")};ids=append(ids,id);keys=append(keys,key);t.Logf("isolated_actor=api-token:%d",id)}
 engine,_:=url.Parse("http://127.0.0.1:17890");a:=&app{db:db,engine:engine};mux:=http.NewServeMux();mux.HandleFunc("/v1/legal/",a.publicLegalAPI);mux.HandleFunc("/v1/chat/completions",a.publicAIChatCompletions);srv:=httptest.NewServer(mux);defer srv.Close();base:=srv.URL;if os.Getenv("HARMONIKA_LEGAL_BASE")!=""{base=os.Getenv("HARMONIKA_LEGAL_BASE")}
 call:=func(method,path string,input any,key string,status int,idem string)map[string]any{
  b,_:=json.Marshal(input);r,_:=http.NewRequestWithContext(ctx,method,base+path,bytes.NewReader(b));r.Header.Set("Authorization","Bearer "+key);r.Header.Set("Content-Type","application/json");r.Header.Set("X-Harmonika-Principal",fmt.Sprintf("api-token:%d",ids[1]));r.Header.Set("X-Harmonika-Legal-Observer","1");if idem!=""{r.Header.Set("Idempotency-Key",idem)}
  res,err:=http.DefaultClient.Do(r);if err!=nil{t.Fatal(err)};defer res.Body.Close();raw,_:=io.ReadAll(io.LimitReader(res.Body,1048577));if res.StatusCode!=status{t.Fatalf("%s want%d got%d %.1000s",path,status,res.StatusCode,raw)};v:=map[string]any{};if json.Unmarshal(raw,&v)!=nil{t.Fatal("invalid JSON")};return v}
 pub:=call("GET","/v1/legal/capabilities",nil,keys[0],200,"");priv:=call("GET","/v1/legal/capabilities",nil,keys[1],200,"")
 if pub["document_actual_skills"]!=float64(99)||pub["features"].(map[string]any)["legal_vision"]!=false||priv["features"].(map[string]any)["legal_vision"]!=true{t.Fatal("catalog or internal observer guard failed")}
 call("GET","/v1/legal/capabilities",nil,"invalid",401,"")
 input:=map[string]any{"topic":"Uji edukasi ITE bukan perkara nyata","facts":"PRIVATE_LEGAL_LIVE_FIXTURE","jurisdiction":"ID","occurred_on":"2026-01-02","perspective":"terlapor"}
 created:=call("POST","/v1/legal/cases",input,keys[1],200,"fixture-case");cid:=created["result"].(map[string]any)["case"].(map[string]any)["id"].(string)
 call("GET","/v1/legal/cases/"+cid,nil,keys[0],404,"");call("GET","/v1/legal/requests/"+created["id"].(string),nil,keys[0],404,"")
 replay:=call("POST","/v1/legal/cases",input,keys[1],200,"fixture-case");if replay["id"]!=created["id"]||replay["replayed"]!=true{t.Fatal("case idempotency lost")};call("POST","/v1/legal/cases",map[string]any{"topic":"different","facts":"different"},keys[1],409,"fixture-case")
 query:=call("POST","/v1/legal/invoke",map[string]any{"skill_id":"kb.uu.search","input":map[string]any{"query":"Informasi Transaksi Elektronik"}},keys[1],200,"fixture-sources");if len(query["result"].(map[string]any)["matches"].([]any))==0{t.Fatal("real official source corpus empty")}
 call("POST","/v1/legal/invoke",map[string]any{"skill_id":"evidence.vlm.analyze","input":map[string]any{"case_id":cid,"file_id":"fake"}},keys[0],503,"fixture-forbidden-observer")
 fixture,e:=os.ReadFile("/opt/harmonika-ai/legal-vision-fixture.png");if e!=nil{t.Fatal("synthetic image unavailable")};var body bytes.Buffer;writer:=multipart.NewWriter(&body);writer.WriteField("case_id",cid);part,_:=writer.CreateFormFile("file","fixture.png");part.Write(fixture);writer.Close();req,_:=http.NewRequestWithContext(ctx,"POST",base+"/v1/legal/files",&body);req.Header.Set("Authorization","Bearer "+keys[1]);req.Header.Set("Content-Type",writer.FormDataContentType());res,err:=http.DefaultClient.Do(req);if err!=nil{t.Fatal(err)};raw,_:=io.ReadAll(res.Body);res.Body.Close();if res.StatusCode!=201{t.Fatalf("upload%d %.500s",res.StatusCode,raw)};uploaded:=map[string]any{};json.Unmarshal(raw,&uploaded);file:=uploaded["file"].(map[string]any);fid:=file["file_id"].(string);if file["encryption"]!="AES-256-GCM"||file["mime_type"]!="image/png"{t.Fatal("upload missing actual cipher/MIME")}
 call("GET","/v1/legal/files/"+fid+"/download",nil,keys[0],404,"")
 req,_=http.NewRequestWithContext(ctx,"GET",base+"/v1/legal/files/"+fid+"/download",nil);req.Header.Set("Authorization","Bearer "+keys[1]);res,err=http.DefaultClient.Do(req);if err!=nil{t.Fatal(err)};downloaded,_:=io.ReadAll(res.Body);res.Body.Close();if res.StatusCode!=200||!bytes.Equal(fixture,downloaded){t.Fatal("private original download mismatch")}
 observed:=call("POST","/v1/legal/invoke",map[string]any{"skill_id":"evidence.vlm.analyze","input":map[string]any{"case_id":cid,"file_id":fid}},keys[1],200,"fixture-real-vision");o:=observed["result"].(map[string]any);if o["analysis_performed"]!=true||o["legal_fact_verified"]!=false||!strings.Contains(o["observations"].(map[string]any)["text_detected"].(string),"7319"){t.Fatalf("real observer missing/false facts: %.1000s",mustJSON(observed))}
 chat:=call("POST","/v1/chat/completions",map[string]any{"model":"harmonika-ai","legal":true,"legal_case_id":cid,"messages":[]map[string]string{{"role":"user","content":"Apa yang perlu saya periksa tanpa menyimpulkan salah atau benar?"}}},keys[1],200,"fixture-chat");meta:=chat["harmonika"].(map[string]any);r:=meta["result"].(map[string]any);if r["applicability_determined"]!=false||len(r["citations"].([]any))==0||!strings.Contains(r["text"].(string),"bukan nasihat hukum"){t.Fatal("grounding or caveats missing")}
 recovery:=call("GET","/v1/legal/cases/"+cid,nil,keys[1],200,"");if len(recovery["messages"].([]any))!=2{t.Fatal("case chat history missing")}
 er,_:=http.NewRequestWithContext(ctx,"GET",base+"/v1/legal/requests/"+meta["id"].(string)+"/events",nil);er.Header.Set("Authorization","Bearer "+keys[1]);er.Header.Set("Accept","text/event-stream");er.Header.Set("Last-Event-ID",meta["id"].(string)+":1");es,e:=http.DefaultClient.Do(er);if e!=nil{t.Fatal(e)};events,_:=io.ReadAll(es.Body);es.Body.Close();if es.StatusCode!=200||!strings.Contains(string(events),"[DONE]")||strings.Contains(string(events),"id: "+meta["id"].(string)+":1\n"){t.Fatal("SSE replay failed")}
 t.Log("legal real source/case history/internal vision/public guard/encrypted upload/Bearer original/SSE PASS")
}
